/** A user-facing term. Internal and inspection-only terms are not TermIds and have no label. */
export type TermId = keyof typeof LABELS;
export type LabelOption<T extends TermId> = Extract<keyof (typeof LABELS)[T]['options'], string>;

export interface LabelOptions<T extends TermId> {
  /** Label option for terms labeled by stage, kind, or submission state. Defaults to the term's default option. */
  option?: LabelOption<T>;
  /** Returns the plural form when set and not 1. */
  count?: number;
}

/** The user-facing label of a term. Throws for an unknown or non-user-facing term: there is no internal-term fallback. */
export function label<T extends TermId>(termId: T, opts: LabelOptions<T> = {}): string {
  const entry = (LABELS as Readonly<Record<string, LabelEntry>>)[termId];
  if (!entry) throw new Error(`No user-facing label for "${String(termId)}"`);
  const key: string = opts.option ?? entry.default;
  const forms = entry.options[key];
  if (!forms) throw new Error(`"${termId}" has no label option "${key}"`);
  return opts.count === undefined || opts.count === 1 ? forms[0] : forms[1];
}

